<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['reseller']); $s=$db->prepare('SELECT id FROM resellers WHERE user_id=? LIMIT 1');$s->execute([$u['id']]);$r=$s->fetch();if(!$r)exit('Reseller profile not found.');$rid=(int)$r['id'];$msg=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$db->prepare('SELECT id,domain FROM licenses WHERE id=? AND reseller_id=?');$s->execute([(int)$_POST['license_id'],$rid]);$l=$s->fetch();if($l&&trim($_POST['new_domain'])){$q=$db->prepare('INSERT INTO reissue_requests(license_id,reseller_id,current_domain,new_domain,reason,status) VALUES(?,?,?,?,?,"pending")');$q->execute([$l['id'],$rid,$l['domain'],trim($_POST['new_domain']),trim($_POST['reason'])?:null]);$msg='Reissue request submitted.';}}
$s=$db->prepare('SELECT id,license_key,domain,status,expires_at FROM licenses WHERE reseller_id=? ORDER BY id DESC');$s->execute([$rid]);$licenses=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkyNoc Reseller</title><style>body{font-family:Arial;background:#f5f7fa;margin:0}.nav{background:#111827;color:#fff;padding:16px 24px}.wrap{max-width:1000px;margin:25px auto;padding:0 16px}.card{background:#fff;padding:18px;border-radius:10px;margin-bottom:16px}table{width:100%;border-collapse:collapse;background:#fff}td,th{padding:10px;border-bottom:1px solid #eee;text-align:left}input,textarea,button{padding:9px;width:100%;box-sizing:border-box;margin:4px 0 8px}button{background:#111827;color:#fff;border:0;border-radius:5px}.msg{background:#dcfce7;padding:10px}</style></head><body><div class="nav"><b>SkyNoc Reseller Portal</b> · <?=e($u['name'])?> · <a style="color:#fff" href="/logout.php">Logout</a></div><div class="wrap"><h1>My Licenses</h1><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><table><tr><th>License</th><th>Domain</th><th>Status</th><th>Expires</th></tr><?php foreach($licenses as $l):?><tr><td><?=e($l['license_key'])?></td><td><?=e($l['domain'])?></td><td><?=e($l['status'])?></td><td><?=e($l['expires_at'])?></td></tr><?php endforeach;?></table><div class="card"><h3>Request Reissue</h3><form method="post"><?=csrf_field()?><select name="license_id" required><?php foreach($licenses as $l):?><option value="<?=$l['id']?>"><?=e($l['license_key'].' — '.$l['domain'])?></option><?php endforeach;?></select><input name="new_domain" placeholder="New domain" required><textarea name="reason" placeholder="Reason"></textarea><button>Submit Reissue Request</button></form></div></div></body></html>